#!/usr/bin/env python3
"""Rebuild bundled map: Python >=3.10 + scripts/world_quest_requirements.txt.

Download is SHA-256 pinned. --source supports a previously downloaded source;
--check compares generated bytes without modifying the bundle.
"""
import argparse
import hashlib
import json
import pathlib
import urllib.request

import shapely
from shapely.geometry import Point, shape, mapping
from pyproj import Transformer

ROOT = pathlib.Path(__file__).resolve().parents[1]
URL = 'https://raw.githubusercontent.com/nvkelso/natural-earth-vector/v5.1.2/geojson/ne_10m_admin_0_countries_ind.geojson'
SHA = '3e67a5a6ddeff3247ca8400cd2514fd4a5ac6e5432823b25d610a7028597d45f'
# Explicit roster, not inferred from Natural Earth's country classifications.
ROSTER = '''AFG AGO ALB AND ARE ARG ARM ATG AUS AUT AZE BDI BEL BEN BFA BGD BGR BHR BHS BIH BLR BLZ BOL BRA BRB BRN BTN BWA CAF CAN CHE CHL CHN CIV CMR COD COG COL COM CPV CRI CUB CYP CZE DEU DJI DMA DNK DOM DZA ECU EGY ERI ESP EST ETH FIN FJI FRA FSM GAB GBR GEO GHA GIN GMB GNB GNQ GRC GRD GTM GUY HND HRV HTI HUN IDN IND IRL IRN IRQ ISL ISR ITA JAM JOR JPN KAZ KEN KGZ KHM KIR KNA KOR KWT LAO LBN LBR LBY LCA LIE LKA LSO LTU LUX LVA MAR MCO MDA MDG MDV MEX MHL MKD MLI MLT MMR MNE MNG MOZ MRT MUS MWI MYS NAM NER NGA NIC NLD NOR NPL NRU NZL OMN PAK PAN PER PHL PLW PNG POL PRK PRT PRY PSX QAT ROU RUS RWA SAU SDN SDS SEN SGP SLB SLE SLV SMR SOM SRB STP SUR SVK SVN SWE SWZ SYC SYR TCD TGO THA TJK TKM TLS TON TTO TUN TUR TUV TZA UGA UKR URY USA UZB VAT VCT VEN VNM VUT WSM YEM ZAF ZMB ZWE'''.split()
STARTER = 'IND CHN JPN AUS EGY ZAF FRA ITA GBR USA CAN BRA'.split()
NAMES = {'CHN':'China', 'USA':'United States', 'PSX':'Palestine', 'SDS':'South Sudan',
         'CZE':'Czechia', 'CIV':"Côte d’Ivoire", 'CPV':'Cabo Verde', 'TLS':'Timor-Leste',
         'TUR':'Türkiye', 'BHS':'Bahamas', 'GMB':'Gambia', 'FSM':'Micronesia'}


def build(raw):
    assert hashlib.sha256(raw).hexdigest() == SHA, 'Source checksum mismatch'
    features = json.loads(raw)['features']
    assert len(ROSTER) == len(set(ROSTER)) == 195
    source = [shape(f['geometry']) for f in features]
    assert shapely.coverage_is_valid(source), 'Source shared-edge coverage changed'
    # Coverage simplification processes shared boundaries together, unlike per-country simplify.
    simplified = shapely.coverage_simplify(source, .025)
    project = Transformer.from_crs('EPSG:4326', 'EPSG:8857', always_xy=True)
    xmax = project.transform(180, 0)[0]
    ymax = project.transform(0, 90)[1]

    def point(x, y):
        px, py = project.transform(x, y)
        return [round((px + xmax) / (2*xmax), 7), round((ymax - py) / (2*ymax), 7)]

    countries, geometries = [], []
    for feature, original, geometry in zip(features, source, simplified):
        p = feature['properties']
        code = p['ADM0_A3']
        rings = []
        # Repair the source's one invalid polygon after simplifying its shared boundaries.
        geometry = shapely.make_valid(geometry)
        polygons = list(geometry.geoms) if hasattr(geometry, 'geoms') else [geometry]
        for polygon in polygons:
            if polygon.geom_type != 'Polygon':
                continue
            for ring in [polygon.exterior, *polygon.interiors]:
                # The source is already cut at +/-180, so no edge crosses the map.
                assert all(abs(a[0]-b[0]) < 180.1 or (a[1] < -89.9 and b[1] < -89.9) for a,b in zip(ring.coords, list(ring.coords)[1:]))
                rings.append([point(x, y) for x,y in ring.coords])
        assert rings, f'Missing geometry {code}'
        geometries.append({'id':code, 'rings':rings})
        if code not in ROSTER:
            continue
        lon, lat = p['LABEL_X'], p['LABEL_Y']
        anchor = Point(lon, lat)
        if not original.covers(anchor):
            parts = list(original.geoms) if hasattr(original, 'geoms') else [original]
            anchor = min(parts, key=lambda part: part.distance(anchor)).representative_point()
            lon, lat = anchor.x, anchor.y
        continent = p['REGION_UN']
        if continent == 'Americas':
            continent = 'South America' if p['SUBREGION'] == 'South America' else 'North America'
        countries.append({'id':code, 'name':NAMES.get(code,p['NAME_EN']), 'continent':continent,
                          'anchor':point(lon,lat), 'longitude':round(lon,6), 'latitude':round(lat,6),
                          'area':round(original.area,6)})
    assert {c['id'] for c in countries} == set(ROSTER)
    assert len(STARTER) == 12 and set(STARTER) <= set(ROSTER)
    result = {'schemaVersion':1, 'projection':'Equal Earth (EPSG:8857)',
              'aspectRatio':xmax/ymax, 'boundaryViewpoint':'India', 'sourceVersion':'5.1.2',
              'starterIDs':STARTER, 'countries':sorted(countries,key=lambda c:c['id']),
              'features':sorted(geometries,key=lambda f:f['id'])}
    manifest = {'sourceURL':URL,'sourceSHA256':SHA,'sourceVersion':'5.1.2',
                'license':'Public domain','licenseURL':'https://www.naturalearthdata.com/about/terms-of-use/',
                'boundaryViewpoint':'India','projection':'EPSG:8857',
                'simplification':'shapely.coverage_simplify, tolerance 0.025 degrees; make_valid; round projected normalized coordinates to 7 decimals',
                'dependencies':{'shapely':'2.1.2','pyproj':'3.7.2'},
                'roster':'193 UN members + Palestine + Vatican City (Holy See)',
                'rosterIDs':sorted(ROSTER),'supplementalLocations':[],
                'regionSource':'Natural Earth REGION_UN and SUBREGION; Americas split North/South',
                'territories':'Non-roster features are background only; overseas components retain their source owner.',
                'coordinateCount':sum(len(r) for f in geometries for r in f['rings'])}
    map_content = json.dumps(result,separators=(',',':'),ensure_ascii=False)+'\n'
    manifest['mapSHA256'] = hashlib.sha256(map_content.encode()).hexdigest()
    return {'world-quest-map.json':map_content,
            'provenance.json':json.dumps(manifest,indent=2,ensure_ascii=False)+'\n'}


if __name__ == '__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source',type=pathlib.Path)
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    raw=args.source.read_bytes() if args.source else urllib.request.urlopen(URL,timeout=60).read()
    for name,content in build(raw).items():
        path=ROOT/'Content'/'WorldQuest'/name
        if args.check:
            assert path.read_text()==content, f'Stale generated content: {path}'
        else:
            path.write_text(content)
        print(f'{name}: {len(content.encode()):,} bytes')
